def gen(rng):
    from collections import deque

    def build(vals):
        # insert values in the given order, iteratively
        L, R = [-1] * len(vals), [-1] * len(vals)
        for i in range(1, len(vals)):
            cur = 0
            while True:
                if vals[i] < vals[cur]:
                    if L[cur] == -1:
                        L[cur] = i
                        break
                    cur = L[cur]
                else:
                    if R[cur] == -1:
                        R[cur] = i
                        break
                    cur = R[cur]
        return L, R

    def ser(vals, LR=None):
        L, R = LR if LR else build(vals)
        out = []
        q = deque([0])
        while q:
            x = q.popleft()
            if x == -1:
                out.append('null')
                continue
            out.append(str(vals[x]))
            q.append(L[x])
            q.append(R[x])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def case(vals, p, q, LR=None):
        return ser(vals, LR) + '\n' + str(p) + ' ' + str(q)

    def chain(n, right):
        nxt = [i + 1 for i in range(n - 1)] + [-1]
        none = [-1] * n
        return (none, nxt) if right else (nxt, none)

    def balanced(sorted_vals):
        order = []
        stack = [(0, len(sorted_vals) - 1)]
        while stack:
            lo, hi = stack.pop()
            if lo > hi:
                continue
            mid = (lo + hi) // 2
            order.append(sorted_vals[mid])
            stack.append((mid + 1, hi))
            stack.append((lo, mid - 1))
        return order

    tests = [case([5], 5, 5), case([5, 3], 3, 5), case([5, 3], 3, 3), case([5, 3, 8], 3, 8), case([1, 2, 3, 4], 2, 4),
             case([4, 3, 2, 1], 1, 2), case([10, 5, 15, 2, 7, 12, 20, 6], 6, 7), case([10, 5, 15, 2, 7, 12, 20, 6], 2, 6),
             case([10, 5, 15, 2, 7, 12, 20, 6], 6, 12)]
    for _ in range(25):
        n = rng.randint(2, 14)
        vals = rng.sample(range(1, 60), n)
        tests.append(case(vals, rng.choice(vals), rng.choice(vals)))
    N = 50000
    vs = rng.sample(range(1, 10**6 + 1), N)
    p, q = rng.sample(vs, 2)
    tests.append(case(vs, p, q))
    sv = sorted(vs)
    order = balanced(sv)
    tests.append(case(order, sv[0], sv[-1]))
    tests.append(case(order, sv[1234], sv[1235]))
    tests.append(case(sv, sv[-2], sv[-1], chain(N, True)))
    tests.append(case(sv[::-1], sv[1], sv[0], chain(N, False)))
    return tests
